import glob


def partner_read(path, schema):
    # The partner's import. Don't change it: it rejects a file whose root element isn't <accounts>.
    for name in glob.glob(path + "/part-*.xml"):
        body = open(name).read().split("?>", 1)[-1].strip()
        if body and not body.startswith("<accounts>"):
            raise ValueError("the partner rejected the file: its root element isn't <accounts>")
    return spark.read.option("rowTag", "account").schema(schema).xml(path)


def save(accounts, path):
    accounts.write.option("rowTag", "accounts").option("rootTag", "account").xml(path)


def solve(accounts):
    path = "/tmp/partner/accounts_xml"
    save(accounts, path)
    return partner_read(path, accounts.schema)
